export async function sendEmail(msg) {
  for (let attempt = 0; attempt < 3; attempt++) {
    const res = await fetch(process.env.MAIL_URL, { method: 'POST', body: JSON.stringify(msg) });
    if (res.ok) return true;
  }
  return false;
}
